<?php

/**
 * Finds the number with the maximum occurrence in an array.
 * If there are multiple numbers with the same maximum occurrence,
 * returns the smallest one.
 *
 * @param array $numbers An array of numbers.
 * @return int|float The number with the highest frequency.
 */
function getMaxOccurrence(array $numbers)
{
    if (empty($numbers)) {
        return null;
    }

    // Count the occurrences of each number
    $counts = array_count_values($numbers);

    // Find the maximum occurrence count
    $maxCount = max($counts);

    // Filter the numbers that have the maximum occurrence count
    $candidates = array_keys(array_filter($counts, function ($count) use ($maxCount) {
        return $count === $maxCount;
    }));

    // Return the smallest number among the candidates
    return min($candidates);
}
